import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/VARIABLE-ATTRIBUTE.md","filePath":"manual-en/VARIABLE-ATTRIBUTE.md","lastUpdated":1785684581000}'),i={name:"manual-en/VARIABLE-ATTRIBUTE.md"};function o(d,e,s,c,l,T){return t(),r("div",null,[...e[0]||(e[0]=[n(`<h3 id="_11-14-variable-attribute" tabindex="-1">11.14 VARIABLE ATTRIBUTE <a class="header-anchor" href="#_11-14-variable-attribute" aria-label="Permalink to &quot;11.14 VARIABLE ATTRIBUTE&quot;">​</a></h3><p><code>VARIABLE ATTRIBUTE</code> adds, modifies, or removes user-defined attributes associated with variables in the active dataset. Custom variable attributes are not interpreted by PSPP, but they are saved as part of system files and may be used by other software that reads them.</p><pre><code>VARIABLE ATTRIBUTE
         VARIABLES=var_list
         ATTRIBUTE=name(’value’) [name(’value’)]…
         ATTRIBUTE=name**[** index**]**(’value’) [name**[** index**]**(’value’)]…
         DELETE=name [name]…
         DELETE=name**[** index**]** [name**[** index**]**]…
</code></pre><p>The required <code>VARIABLES</code> subcommand must come first. Specify the variables to which the following <code>ATTRIBUTE</code> or <code>DELETE</code> subcommand should apply.</p><p>Use the <code>ATTRIBUTE</code> subcommand to add or modify custom variable attributes. Specify the name of the attribute as an identifier (see <a href="./Tokens">Tokens</a>), followed by the desired value, in parentheses, as a quoted string. The specified attributes are then added or modified in the variables specified on <code>VARIABLES</code>. Attribute names that begin with <code>$</code> are reserved for PSPP’s internal use, and attribute names that begin with <code>@</code> or <code>$@</code> are not displayed by most PSPP commands that display other attributes. Other attribute names are not treated specially.</p><p>Attributes may also be organized into arrays. To assign to an array element, add an integer array index enclosed in square brackets (<code>[</code> and <code>]</code>) between the attribute name and value. Array indexes start at 1, not 0. An attribute array that has a single element (number 1) is not distinguished from a non-array attribute.</p><p>Use the <code>DELETE</code> subcommand to delete an attribute from the variable specified on <code>VARIABLES</code>. Specify an attribute name by itself to delete an entire attribute, including all array elements for attribute arrays. Specify an attribute name followed by an array index in square brackets to delete a single element of an attribute array. In the latter case, all the array elements numbered higher than the deleted element are shifted down, filling the vacated position.</p><p>To associate custom attributes with the entire active dataset, instead of with particular variables, use <code>DATAFILE ATTRIBUTE</code> (see <a href="./DATAFILE-ATTRIBUTE">DATAFILE ATTRIBUTE</a>) instead.</p><p><code>VARIABLE ATTRIBUTE</code> takes effect immediately. It is not affected by conditional and looping structures such as <code>DO IF</code> or <code>LOOP</code>.</p>`,9)])])}const A=a(i,[["render",o]]);export{u as __pageData,A as default};
